from smart_contracts.deploy_common import deploy_typed


# Deploys AirCargoProvenance, funds it for box storage and records its app id in
# smart_contracts/artifacts/deployed_apps.json (read by the API).
# The typed client is generated by `algokit project run build`.
def deploy() -> None:
    from smart_contracts.artifacts.hello_world.air_cargo_provenance_client import (
        AirCargoProvenanceFactory,
    )

    deploy_typed("hello_world", AirCargoProvenanceFactory)
